// zigbee2mqtt sensor -> wall-panel tiles: wallpanel/tiles/sensors/<key>
//
// Contract: kiosk-display/docs/todo-view-mechanisms.md (generic tiles renderer).
// The panel only renders; formatting and judgement live here, so the same
// tile could drive a phone notification later.
//
// EDIT ON IMPORT: replace the friendly names with your own zigbee2mqtt devices
// and drop the readings you don't have. Pick the few that would make someone
// get up - a dozen numbers on the wall read as wallpaper (docs/todo-sensors.md).
const SENSORS = {
    "LIVINGROOM_AIR": [
        { key: "co2",     field: "co2",         label: "CO₂ living room", unit: "ppm", decimals: 0, rule: "co2",      hero: true, order: 10 },
        { key: "pm25",    field: "pm25",        label: "PM2.5",               unit: "µg/m³", decimals: 0, rule: "pm25", order: 40 },
    ],
    "LIVINGROOM_TEMP": [
        { key: "temp-in", field: "temperature", label: "Inside",   unit: "°C", decimals: 1, order: 20 },
        { key: "rh-in",   field: "humidity",    label: "Humidity", unit: "%",       decimals: 0, rule: "humidity", order: 30 },
    ],
};

// Thresholds from docs/todo-sensors.md. Starting points, worth arguing with.
const RULES = {
    co2:      v => v > 1200 ? "bad" : v >= 800 ? "warn" : "ok",
    humidity: v => (v > 60 || v < 25) ? "bad" : (v > 50 || v < 30) ? "warn" : "ok",
    pm25:     v => v > 25 ? "bad" : v >= 10 ? "warn" : "ok",
};

const device = String(msg.topic || "").replace(/^zigbee2mqtt\//, "");
const readings = SENSORS[device];
if (!readings || !msg.payload || typeof msg.payload !== "object") return null;

const now = new Date().toISOString();
const out = [];
for (const r of readings) {
    const raw = msg.payload[r.field];
    if (typeof raw !== "number" || !isFinite(raw)) continue;   // not in this report
    const tile = {
        label: r.label,
        value: raw.toFixed(r.decimals),
        unit: r.unit,
        order: r.order,
        updated_at: now,
    };
    if (r.rule && RULES[r.rule]) tile.state = RULES[r.rule](raw);
    if (r.hero) tile.hero = true;
    out.push({ topic: "wallpanel/tiles/sensors/" + r.key, payload: JSON.stringify(tile) });
}
if (!out.length) return null;                 // e.g. a battery-only report
node.status({ fill: "green", shape: "dot", text: device + " → " + out.length + " tile(s)" });
return [out];
